function validate([descriptions]) {
  if (!Array.isArray(descriptions) || descriptions.length < 1 || descriptions.length > 10000) return 'descriptions needs 1 to 10^4 triples.';
  const parentOf = new Map();
  const slots = new Set();
  const kids = new Map();
  for (const d of descriptions) {
    if (!Array.isArray(d) || d.length !== 3) return 'Each description is [parent, child, isLeft].';
    const [parent, child, isLeft] = d;
    if (![parent, child].every(v => Number.isInteger(v) && v >= 1 && v <= 100000)) return 'Node values are integers between 1 and 10^5.';
    if (isLeft !== 0 && isLeft !== 1) return 'isLeft must be 0 or 1.';
    if (parent === child) return 'A node cannot be its own child.';
    if (parentOf.has(child)) return `Node ${child} has more than one parent.`;
    parentOf.set(child, parent);
    const slot = parent * 2 + isLeft;
    if (slots.has(slot)) return `Node ${parent} has two ${isLeft ? 'left' : 'right'} children.`;
    slots.add(slot);
    if (!kids.has(parent)) kids.set(parent, []);
    kids.get(parent).push(child);
  }
  const roots = [...kids.keys()].filter(v => !parentOf.has(v));
  if (roots.length !== 1) return 'The descriptions must form a single tree with exactly one root.';
  // Every node has at most one parent, so this walk cannot loop; it must reach every node.
  let reached = 0;
  const stack = [roots[0]];
  while (stack.length) {
    const value = stack.pop();
    reached++;
    for (const child of kids.get(value) ?? []) stack.push(child);
  }
  if (reached !== parentOf.size + 1) return 'The descriptions must form a single tree without cycles.';
  return null;
}

