  // The root is the one parent value that never appears in the child column.
  let rootValue = null;
  for (const [parent] of descriptions) {
    if (!descriptions.some(d => d[1] === parent)) rootValue = parent;
  }
  // Grow the tree downwards, scanning the whole list for each node's children.
  const build = value => {
    const node = new TreeNode(value);
    for (const [parent, child, isLeft] of descriptions) {
      if (parent !== value) continue;
      if (isLeft === 1) node.left = build(child);
      else node.right = build(child);
    }
    return node;
  };
  return build(rootValue);
}

