function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const count = size === 'large' ? int(1500, 2001) : int(2, 9);
  // Distinct node values, sometimes packed close together, sometimes spread up to 10^5.
  const top = size === 'large' || rand() < 0.3 ? 100000 : 3 * count;
  const used = new Set();
  const values = [];
  while (values.length < count) {
    const value = rand() < 0.05 ? (rand() < 0.5 ? 1 : 100000) : int(1, top);
    if (!used.has(value)) {
      used.add(value);
      values.push(value);
    }
  }
  // Free child slots as [node index, isLeft]; the tree shape depends on which slot is filled next.
  const shape = rand();
  const open = [[0, 1], [0, 0]];
  const descriptions = [];
  for (let i = 1; i < count; i++) {
    let pick;
    if (shape < 0.2) pick = open.length - 1 - int(0, 1); // a path: always below the newest node
    else if (shape < 0.4) pick = 0; // breadth-first: a complete tree
    else pick = int(0, open.length - 1); // a random tree
    const [slotNode, isLeft] = open[pick];
    open.splice(pick, 1);
    descriptions.push([values[slotNode], values[i], isLeft]);
    open.push([i, 1], [i, 0]);
  }
  // Shuffle the triples so parents can appear after their children.
  if (size === 'large' || rand() < 0.8) {
    for (let i = descriptions.length - 1; i > 0; i--) {
      const j = int(0, i);
      [descriptions[i], descriptions[j]] = [descriptions[j], descriptions[i]];
    }
  }
  return [descriptions];
}
